// DimPriority — generated by src/powerbi/build_assets.py from DimPriority.csv
// Grain/keys: see powerbi/data_model.md
let
    Source   = Csv.Document(File.Contents(DataFolder & "DimPriority.csv"),
                            [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
    Promoted = Table.PromoteHeaders(Source, [PromoteAllScalars = true]),
    Typed    = Table.TransformColumnTypes(Promoted, {
        {"priority_key", Int64.Type},
        {"ticket_priority", type text},
        {"priority_sort", Int64.Type},
        {"sla_target_hours", Int64.Type},
        {"frt_target_hours", Int64.Type}
    }, "en-US")
in
    Typed
